1|// Pure narration logic: sentence split, chunking, cache keys, manifest
2|// validation, playback helpers, and cost math. No env, no network,
3|// no crypto, no node: imports; callers inject hashing.
4|export const NARRATION_VOICE = "af_heart";
5|export const NARRATION_MODEL = "kokoro-82m/0.9.4";
6|export const NARRATION_SPEED = 0.95;
7|export const NARRATION_FORMAT = 1;
8|export const SENTENCE_GAP_SEC = 0.3;
9|export const PARAGRAPH_GAP_SEC = 0.7;
10|
11|export interface SentenceSpan {
12|  start: number;
13|  end: number;
14|}
15|
16|export interface NarrationChunk {
17|  n: number;
18|  start: number;
19|  end: number;
20|  text: string;
21|}
22|
23|const CLOSERS = new Set(["”", "’", '"', "'", ")", "]"]);
24|
25|// Lowercase words that end with a period without ending a sentence.
26|const ABBREVIATIONS = new Set([
27|  "mr", "mrs", "ms", "dr", "st", "mt", "prof", "sr", "jr",
28|  "rev", "lt", "col", "gen", "capt", "sgt", "ave", "blvd", "rd", "no",
29|]);
30|
31|function isTerminator(char: string): boolean {
32|  return char === "." || char === "!" || char === "?" || char === "…";
33|}
34|
35|function isSpace(char: string | undefined): boolean {
36|  return char === undefined || /\s/.test(char);
37|}
38|
39|// Word of letters directly before index (exclusive), lowercased.
40|function wordBefore(text: string, index: number): string {
41|  let i = index - 1;
42|  while (i >= 0 && /[A-Za-z]/.test(text[i] as string)) i -= 1;
43|  return text.slice(i + 1, index).toLowerCase();
44|}
45|
46|function wordCount(piece: string): number {
47|  const words = piece.split(/\s+/).filter((w) => w.length > 0);
48|  return words.length;
49|}
50|
51|// Char offsets into the paragraph text, trimmed of surrounding
52|// whitespace, covering every non-space char. A sentence ends at a
53|// terminator plus closing quotes/brackets followed by whitespace.
54|export function splitSentences(text: string): SentenceSpan[] {
55|  const raw: SentenceSpan[] = [];
56|  let pieceStart = -1;
57|  let i = 0;
58|  while (i < text.length) {
59|    const char = text[i] as string;
60|    if (/\s/.test(char)) {
61|      i += 1;
62|      continue;
63|    }
64|    if (pieceStart === -1) pieceStart = i;
65|    if (isTerminator(char)) {
66|      let end = i + 1;
67|      while (end < text.length && CLOSERS.has(text[end] as string)) end += 1;
68|      if (isSpace(text[end])) {
69|        if (char === ".") {
70|          const word = wordBefore(text, i);
71|          const singleInitial = /^[A-Z]$/.test(text.slice(i - 1, i));
72|          if (singleInitial || ABBREVIATIONS.has(word)) {
73|            i += 1;
74|            continue;
75|          }
76|        }
77|        // Trim trailing whitespace inside the piece (there is none:
78|        // the piece ends at a terminator or closer).
79|        raw.push({ start: pieceStart, end });
80|        pieceStart = -1;
81|        i = end;
82|        continue;
83|      }
84|    }
85|    i += 1;
86|  }
87|  if (pieceStart !== -1) {
88|    let end = text.length;
89|    while (end > pieceStart && /\s/.test(text[end - 1] as string)) end -= 1;
90|    raw.push({ start: pieceStart, end });
91|  }
92|  if (raw.length === 0) return [];
93|  // Merge a piece shorter than 3 words into the previous sentence
94|  // (or the next one if first), keeping offsets exact.
95|  const merged: SentenceSpan[] = [];
96|  for (const span of raw) {
97|    const piece = text.slice(span.start, span.end);
98|    if (wordCount(piece) >= 3 || merged.length === 0) {
99|      merged.push({ ...span });
100|      continue;
101|    }
102|    const prev = merged[merged.length - 1] as SentenceSpan;
103|    prev.end = span.end;
104|  }
105|  if (merged.length > 1) {
106|    const first = merged[0] as SentenceSpan;
107|    if (wordCount(text.slice(first.start, first.end)) < 3) {
108|      const next = merged[1] as SentenceSpan;
109|      next.start = first.start;
110|      merged.shift();
111|    }
112|  }
113|  return merged;
114|}
115|
116|export function chapterChunks(paragraphs: { n: number; text: string }[]): {
117|  chunks: NarrationChunk[];
118|  gaps: number[];
119|} {
120|  const chunks: NarrationChunk[] = [];
121|  const paraOf: number[] = [];
122|  paragraphs.forEach((para, paraIndex) => {
123|    for (const span of splitSentences(para.text)) {
124|      chunks.push({ n: para.n, start: span.start, end: span.end, text: para.text.slice(span.start, span.end) });
125|      paraOf.push(paraIndex);
126|    }
127|  });
128|  const gaps = chunks.map((_, i) => {
129|    if (i === chunks.length - 1) return 0;
130|    return paraOf[i] !== paraOf[i + 1] ? PARAGRAPH_GAP_SEC : SENTENCE_GAP_SEC;
131|  });
132|  return { chunks, gaps };
133|}
