135|export function normalizeChunkText(text: string): string {
136|  return text.normalize("NFC").replace(/\s+/g, " ").trim();
137|}
138|
139|// Canonical string the caller hashes with SHA-256. Same text + voice +
140|// model + speed => same string; any edit changes it.
141|export function narrationKeyInput(args: {
142|  chunks: { text: string }[];
143|  voice: string;
144|  model: string;
145|  speed: number;
146|  format: number;
147|}): string {
148|  const body = args.chunks.map((c) => normalizeChunkText(c.text)).join("\n");
149|  return `narration/${args.format}\nvoice:${args.voice}\nmodel:${args.model}\nspeed:${args.speed}\n${body}`;
150|}
