234|function isSafeSrc(src: string): boolean {
235|  if (src.startsWith("/narration/")) return true;
236|  if (src.startsWith("https://")) {
237|    try {
238|      new URL(src);
239|      return true;
240|    } catch {
241|      return false;
242|    }
243|  }
244|  return false;
245|}
