247|// Binary search: index of the last chunk with t0 <= t, so the highlight
248|// stays on a sentence through the gap after it. -1 before the first.
249|export function activeChunkAt(chunks: { t0: number }[], tSec: number): number {
250|  let lo = 0;
251|  let hi = chunks.length - 1;
252|  let found = -1;
253|  while (lo <= hi) {
254|    const mid = (lo + hi) >> 1;
255|    if ((chunks[mid] as { t0: number }).t0 <= tSec) {
256|      found = mid;
257|      lo = mid + 1;
258|    } else {
259|      hi = mid - 1;
260|    }
261|  }
262|  return found;
263|}
264|
265|// Playback range for a scene: t0 of the first chunk with n >= startN
266|// through t1 of the last chunk with n <= endN. Null when empty.
267|export function sceneSpan(
268|  narration: { chunks: { n: number; t0: number; t1: number }[] },
269|  startN: number,
270|  endN: number,
271|): { startSec: number; endSec: number } | null {
272|  let startSec: number | null = null;
273|  let endSec: number | null = null;
274|  for (const chunk of narration.chunks) {
275|    if (chunk.n < startN || chunk.n > endN) continue;
276|    if (startSec === null) startSec = chunk.t0;
277|    endSec = chunk.t1;
278|  }
279|  if (startSec === null || endSec === null) return null;
280|  return { startSec, endSec };
281|}
282|
283|export type PrepareEvent = "upload" | "enter" | "jump";
284|
285|// Owner's rolling window: upload warms chapters 1-2 while the book is
286|// processed; entering N warms N+1 and N+2; jumping to N warms N and N+1.
287|export function chaptersToPrepare(event: PrepareEvent, ch: number, totalChapters: number): number[] {
288|  const wanted = event === "upload" ? [1, 2] : event === "enter" ? [ch + 1, ch + 2] : [ch, ch + 1];
289|  const seen = new Set<number>();
290|  const out: number[] = [];
291|  for (const n of wanted) {
292|    if (n < 1 || n > totalChapters || seen.has(n)) continue;
293|    seen.add(n);
294|    out.push(n);
295|  }
296|  return out;
297|}
298|
299|// Modal L4, about USD 0.80/h.
300|export const KOKORO_L4_USD_PER_SEC = 0.000222;
301|
302|// About 15 chars of audio per second, GPU time about 2% of audio after
303|// encode, plus 8 s of cold start/overhead. Integer micro-dollars.
304|export function estimateNarrationMicro(chars: number): number {
305|  return Math.ceil((Math.max(0, chars) / 15 * 0.02 + 8) * KOKORO_L4_USD_PER_SEC * 1e6);
306|}
307|
308|export function actualNarrationMicro(gpuSec: number): number {
309|  return Math.ceil(Math.max(0, gpuSec) * KOKORO_L4_USD_PER_SEC * 1e6);
310|}

