118|  const keys = narrateKeys(ctx.dir);
119|  if (decide(ctx.force, keys.recorded, keys.current).reuse) {
120|    console.log("narrate: reuse (inputs unchanged)");
121|    return { generated: 0, cached: book.chapters.length, gpuSec: 0, estimatedMicro: 0, actualMicro: 0, stopped: false };
122|  }
123|  const outPath = join(ctx.dir, "narration.json");
124|  const previous = (() => {
125|    try {
126|      return JSON.parse(readFileSync(outPath, "utf8")) as {
127|        chapters?: Record<string, ChapterNarration>;
128|      };
129|    } catch {
130|      return null;
131|    }
132|  })();
133|  const byKey = new Map<string, ChapterNarration>();
134|  for (const manifest of Object.values(previous?.chapters ?? {})) byKey.set(manifest.key, manifest);
135|  const store = deps.store ?? (process.env.BLOB_READ_WRITE_TOKEN ? createBlobNarrationStore() : createLocalNarrationStore("public"));
136|  const capMicro = Math.round((deps.capUsd ?? parseCapUsd(process.env.NARRATION_CAP_USD)) * 1_000_000);
137|  let spent = 0;
138|  const budget = {
139|    reserve: async (micro: number) => {
140|      if (spent + micro > capMicro) return false;
141|      spent += micro;
142|      return true;
143|    },
144|    refund: async (micro: number) => {
145|      spent -= micro;
146|    },
147|  };
148|  const stats: NarrateStats = { generated: 0, cached: 0, gpuSec: 0, estimatedMicro: 0, actualMicro: 0, stopped: false };
149|  const chapters: Record<string, ChapterNarration> = {};
150|  const failed: number[] = [];
151|  // Bounded pool that stops starting new chapters once the cap refuses,
152|  // so the run reports instead of spending more.
153|  let next = 0;
154|  const sha256Hex = async (text: string): Promise<string> => createHash("sha256").update(text).digest("hex");
155|  const one = async (ch: number): Promise<void> => {
156|    const paras = book.paragraphs
157|      .filter((p) => p.ch === ch)
158|      .sort((a, b) => a.n - b.n)
159|      .map((p) => ({ n: p.n, text: p.text }));
160|    const { chunks, gaps } = chapterChunks(paras);
161|    let gpuSec = 0;
162|    const result = await ensureChapterNarration(
163|      { chunks, gaps },
164|      {
165|        sha256Hex,
166|        index: {
167|          get: async (key: string) => byKey.get(key) ?? null,
168|          set: async (key: string, value: ChapterNarration) => {
169|            byKey.set(key, value);
170|          },
171|        },
172|        store,
173|        budget,
174|        synthesize: async (req) => {
175|          const out = await deps.synthesize(req);
176|          gpuSec = out.gpuSec;
177|          return out;
178|        },
179|      },
180|    );
181|    if (result.status === "error" && result.code === "budget") {
182|      stats.stopped = true;
183|      return;
184|    }
185|    // A failed chapter must not lose the paid chapters: record it, keep
186|    // going, and fail only after the ready chapters are written.
187|    if (result.status !== "ready") {
188|      failed.push(ch);
189|      return;
190|    }
191|    chapters[String(ch)] = result.narration;
192|    if (result.cached) {
193|      stats.cached += 1;
194|      console.log(`ch ${ch}: cached`);
195|    } else {
196|      stats.generated += 1;
197|      stats.gpuSec += gpuSec;
198|      stats.estimatedMicro += result.costMicro;
199|      stats.actualMicro += actualNarrationMicro(gpuSec);
200|      console.log(`ch ${ch}: generated ${result.narration.durationSec.toFixed(1)} s audio, ${gpuSec.toFixed(1)} s gpu`);
201|    }
202|  };
203|  const workers = new Array(Math.min(NARRATION_CONCURRENCY, book.chapters.length)).fill(null).map(async () => {
204|    while (next < book.chapters.length && !stats.stopped) {
